/** FA Studio app icon — 512x512 user-provided asset. */
var APP_FAVICON_B64_ = "";
var APP_FAVICON_VERSION_ = "8";

function buildAppFaviconDriveUrl_(fileId) {
  return "https://drive.google.com/uc?id=" + fileId + "&export=download&format=png";
}

function ensureAppFaviconDriveFile_() {
  var props = PropertiesService.getScriptProperties();
  var version = APP_FAVICON_VERSION_;
  var bytes = Utilities.base64Decode(APP_FAVICON_B64_);
  var blob = Utilities.newBlob(bytes, "image/png", "fa-app-icon.png");
  var existingId = props.getProperty("APP_FAVICON_FILE_ID");
  var storedVersion = props.getProperty("APP_FAVICON_VERSION") || "";

  if (existingId && storedVersion === version) {
    try {
      DriveApp.getFileById(existingId);
      return existingId;
    } catch (err) {
      props.deleteProperty("APP_FAVICON_FILE_ID");
      props.deleteProperty("APP_FAVICON_URL");
    }
  }

  if (existingId && storedVersion !== version) {
    try {
      DriveApp.getFileById(existingId).setContent(blob.getBytes()).setName("fa-app-icon.png");
      props.setProperty("APP_FAVICON_VERSION", version);
      props.setProperty("APP_FAVICON_URL", buildAppFaviconDriveUrl_(existingId));
      return existingId;
    } catch (err) {
      props.deleteProperty("APP_FAVICON_FILE_ID");
      props.deleteProperty("APP_FAVICON_URL");
    }
  }

  var folderId = getConfig_("DRIVE_FOLDER_ID") || "";
  var file;
  if (folderId) {
    try {
      file = DriveApp.getFolderById(folderId).createFile(blob);
    } catch (err) {
      file = DriveApp.createFile(blob);
    }
  } else {
    file = DriveApp.createFile(blob);
  }
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  var fileId = file.getId();
  props.setProperty("APP_FAVICON_FILE_ID", fileId);
  props.setProperty("APP_FAVICON_VERSION", version);
  props.setProperty("APP_FAVICON_URL", buildAppFaviconDriveUrl_(fileId));
  return fileId;
}

function getAppFaviconUrl_() {
  ensureAppFaviconDriveFile_();
  return PropertiesService.getScriptProperties().getProperty("APP_FAVICON_URL") || "";
}
